import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    st = [0] * n
    for i in range(n):
        st[i] = int(next(it))

    adj = [[] for _ in range(n)]
    adjr = [[] for _ in range(n)]

    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        adjr[v].append(u)

    mark = [False] * n
    ans = [0] * n

    # DFS 1: Forward from nodes with st == 1
    for i in range(n):
        if not mark[i] and st[i] == 1:
            stack = [i]
            while stack:
                x = stack.pop()
                if mark[x]:
                    continue
                mark[x] = True
                ans[x] += 1
                for u in adj[x]:
                    if not mark[u]:
                        stack.append(u)

    # DFS 2: Reverse from nodes with st == 2, stop at st == 1
    mark = [False] * n
    for i in range(n):
        if not mark[i] and st[i] == 2:
            stack = [i]
            while stack:
                x = stack.pop()
                if mark[x]:
                    continue
                mark[x] = True
                ans[x] += 1
                if st[x] == 1:
                    continue
                for u in adjr[x]:
                    if not mark[u]:
                        stack.append(u)

    out = ['1' if ans[i] == 2 else '0' for i in range(n)]
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    solve()

